import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    idx = 1
    mat = []
    for _ in range(n):
        mat.append([int(x) for x in data[idx:idx+n]])
        idx += n
    for col in range(n):
        row_vals = [str(mat[row][col]) for row in range(n - 1, -1, -1)]
        print(" ".join(row_vals))

if __name__ == '__main__':
    solve()

