#include <stdio.h>

int mat[55][55];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &mat[i][j]);
        }
    }
    for (int col = 0; col < n; col++) {
        for (int row = n - 1; row >= 0; row--) {
            printf("%d%s", mat[row][col], row > 0 ? " " : "");
        }
        printf("\n");
    }
    return 0;
}
